def transform(g):
    h=len(g); w=len(g[0]); out=[r[:] for r in g]
    runs=[]
    for r,row in enumerate(g):
        c=0
        while c<w:
            if row[c]:
                st=c
                while c<w and row[c]: c+=1
                if c-st>1: runs.append((r,st,row[st:c]))
            else: c+=1
    seeds=[seq for _,_,seq in runs]
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v and all(not (rr==r and st<=c<st+len(seq)) for rr,st,seq in runs):
                for seq in seeds:
                    if v in seq:
                        start=c-seq.index(v)
                        for j,x in enumerate(seq):
                            if 0<=start+j<w: out[r][start+j]=x
    return out
